def transform(grid):
    h, w = len(grid), len(grid[0])
    rows, cols = set(), set()

    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 0
                   for rr in (r, r + 1)
                   for cc in (c, c + 1)):
                rows.update((r, r + 1))
                cols.update((c, c + 1))
                break
        if rows:
            break

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if (r in rows or c in cols) and grid[r][c] != 2:
                out[r][c] = 0
    return out
